SOURCE_CLAIM_JSON: {"title":"8th Five Year Plan (English Version)","publisher":"General Economics Division, Bangladesh Planning Commission","publication_date":"2022-04-15","url":"https://gedkp.gov.bd/knowledge-archive/five-year-plans/plan-documents/?cn=five-year-plans-plan-documents","claim":"The Eighth Five Year Plan blends COVID-19 recovery strategies into the macroeconomic framework and aims to implement Perspective Plan 2021-2041 so Bangladesh can reach upper-middle-income status by 2031 and eliminate extreme poverty by 2031.","locator":"lines 265-267","source_type":"official","source_confidence":"high","source_confidence_reason":"Direct government planning document from the responsible planning body with explicit objectives and timeline.","final_evidence_use":"final_evidence","period_fit":"2022 planning document for the target period","ruler_attribution":"Indirect but strong: this is the government planning apparatus under Hasina's administration.","contrary_evidence":["It is a plan statement, not proof of later delivery by itself."],"lenses":["8B.1","8B.2","8B.10"]}
